CREATE TABLE IF NOT EXISTS lr_serverless_aws_us_catalog.bricksurance_reference.certification_attestation (
  element STRING NOT NULL COMMENT 'Model element (entity or metric) that is certified.',
  element_kind STRING NOT NULL COMMENT 'Kind of element: entity or metric_view.',
  certification STRING NOT NULL COMMENT 'Certification level attested.',
  owner STRING NOT NULL COMMENT 'Accountable business owner (org role).',
  attested_by STRING NOT NULL COMMENT 'Role that made the attestation.',
  attested_on STRING NOT NULL COMMENT 'Date of the attestation.',
  evidence STRING COMMENT 'Evidence backing the certification.',
  model_version STRING NOT NULL COMMENT 'Model version this attestation was recorded against.'
)
COMMENT 'The dated attestation behind each certified model element. An element is certified only if it has a row here; the badge is evidence, not a tag. Roles, not people. Grain: One row per certified element per model version.';

ALTER TABLE lr_serverless_aws_us_catalog.bricksurance_reference.certification_attestation ADD CONSTRAINT pk_certification_attestation PRIMARY KEY (element, element_kind, model_version);

ALTER TABLE lr_serverless_aws_us_catalog.bricksurance_reference.certification_attestation SET TAGS ('bxc_model' = 'bricksurance-data-core', 'bxc_model_version' = '0.15.0', 'bxc_domain' = 'reference', 'bxc_maturity' = 'certified');

